import {finite,mean,regressionMetrics} from './core.mjs?v=20261101-lite1';
const eventKeys=['p_mean','p_std','t_mean','t_std','p_delta','t_delta'];
const espKeys=['f_low','f_rms','f_near','f_1x','f_2x','f_a','f_b'];
export const EXTRA_MODELS=[
{id:'event3w',name:'3W井事件分类',en:'3W event classifier',tag:'真实事件特征 · MLP',required:[...eventKeys,'event_code'],target:'event_code',structure:['6项每事件统计特征','24/12 ReLU全连接','Softmax事件类别'],formula:'softmax(W₃ ReLU(W₂ ReLU(W₁x)))',note:'压力MPa、温度°C；3W每事件摘要，event_code为0–9事件类别，不是确诊根因。well_id为原始WELL编号，event_id为事件文件名；无日期要求。'},
{id:'esp',name:'ESP频谱故障分类',en:'ESP spectral classifier',tag:'真实ESP特征 · MLP',required:[...espKeys,'fault'],target:'fault',structure:['7项原始ESP频谱特征','24/12 ReLU全连接','Softmax原始故障标签'],formula:'softmax(W₃ ReLU(W₂ ReLU(W₁x)))',note:'使用all6032原始特征及fault文本标签，保持源数据特征单位；well_id为ESP编号，sample_id为原始样本编号；无日期要求。'},
{id:'horner',name:'Horner试井解释',en:'Horner pressure regression',tag:'分测试最小二乘',required:['log_horner','pressure'],target:'pressure',structure:['按test_id或well_id分组','压力对log10(H)线性回归','截距估计地层压力'],formula:'p = intercept + slope × log10(H)',note:'pressure单位MPa；log_horner为无量纲log10(H)，time_min可选。每组至少3个非恒定横坐标样本；需人工选择有效径向流直线段。'},
{id:'tracer',name:'一维脉冲示踪剂拟合',en:'Pulse advection dispersion',tag:'正参数网格搜索',required:['time_days','concentration','distance_m'],target:'concentration',structure:['按注入井→生产井well_id分组','正v、D网格与非负幅值最小二乘','浓度曲线和L/v运移时间'],formula:'C(t)=A/√(4πDt) × exp(−(L−vt)²/(4Dt))',note:'time_days>0（日），distance_m>0（米），concentration≥0（同一浓度单位）；v米/日，D平方米/日。简化一维脉冲模型，不含吸附、循环回注或多通道。'}
];
const specFor=id=>{const spec=EXTRA_MODELS.find(m=>m.id===id);if(!spec)throw Error('未知监测模型');return spec;};
export function monitoringRequired(id,inference=false){const s=specFor(id);return s.required.filter(k=>!inference||k!==s.target);}
const scalarLabel=v=>typeof v==='string'?v.trim()!=='':typeof v==='number'&&Number.isFinite(v);
function label(id,v){if(id==='event3w'){if(!finite(v)||Number(v)<0||Number(v)>9||!Number.isInteger(Number(v)))throw Error('event_code必须为0–9整数事件类别');return Number(v);}if(!scalarLabel(v))throw Error('fault必须为非空标量标签');return String(v).trim();}
function validate(id,rows,inference=false){if(!Array.isArray(rows)||!rows.length)throw Error('没有有效数据行');const s=specFor(id);for(const [i,r]of rows.entries()){for(const k of monitoringRequired(id,inference)){if(k===s.target&&['event3w','esp'].includes(id))label(id,r[k]);else if(!finite(r[k]))throw Error(`第${i+1}行 ${k} 必须为有限数值`);}if(id==='tracer'&&(!(Number(r.time_days)>0)||!(Number(r.distance_m)>0)||(!inference&&Number(r.concentration)<0)))throw Error('示踪剂要求time_days>0、distance_m>0、concentration≥0');}return rows;}
const groupKey=(id,r)=>String((id==='horner'?r.test_id:undefined)??r.well_id??'').trim();
function groups(id,rows){const out=new Map();for(const r of rows){const k=groupKey(id,r);if(!out.has(k))out.set(k,[]);out.get(k).push(r);}return out;}
const scaled=(fit,r)=>fit.keys.map((k,i)=>(Number(r[k])-fit.scale.mean[i])/fit.scale.std[i]);
const kernel=(t,L,v,D)=>Math.exp(-((L-v*t)**2)/(4*D*t))/Math.sqrt(4*Math.PI*D*t);
const logGrid=(a,b,n)=>Array.from({length:n},(_,i)=>Math.exp(Math.log(a)+(Math.log(b)-Math.log(a))*i/(n-1)));
function tracerFit(rs,options){
  if(rs.length<3||new Set(rs.map(r=>Number(r.time_days))).size<3)return null;
  const ts=rs.map(r=>Number(r.time_days)),Ls=rs.map(r=>Number(r.distance_m)),lo=Math.min(...ts),hi=Math.max(...ts),L=mean(Ls),n=Math.min(80,Math.max(15,Math.floor(Number(options.gridSize)||45)));
  let best=null,vBounds=[L/hi*.2,L/lo*3],dBounds=[L*L/hi*.0001,L*L/lo];
  // Refine the positive log-grid around its best cell to resolve narrow pulses.
  for(let pass=0;pass<3;pass++){
    for(const v of logGrid(...vBounds,n))for(const D of logGrid(...dBounds,n)){
      const ks=rs.map(r=>kernel(Number(r.time_days),Number(r.distance_m),v,D)),den=ks.reduce((s,x)=>s+x*x,0);
      if(den<1e-280)continue;
      const A=Math.max(0,ks.reduce((s,x,i)=>s+x*Number(rs[i].concentration),0)/den),error=mean(ks.map((x,i)=>(A*x-Number(rs[i].concentration))**2));
      if(!best||error<best.loss)best={v,D,A,loss:error};
    }
    if(!best)break;
    const vStep=Math.log(vBounds[1]/vBounds[0])/(n-1),dStep=Math.log(dBounds[1]/dBounds[0])/(n-1);
    vBounds=[best.v*Math.exp(-vStep),best.v*Math.exp(vStep)];dBounds=[best.D*Math.exp(-dStep),best.D*Math.exp(dStep)];
  }
  return best;
}
export async function trainMonitoring(id,rows,val=[],options={},progress=()=>{}){const started=performance.now(),spec=specFor(id);validate(id,rows);const fit={id,target:spec.target,trainRows:rows.map(r=>({...r})),trainedRows:rows.length,history:[],params:{},warnings:[]};if(['event3w','esp'].includes(id)){const tf=globalThis.tf;if(!tf)throw Error('请先加载TensorFlow.js');fit.keys=monitoringRequired(id,true);fit.classes=[...new Set(rows.map(r=>label(id,r[spec.target])))].sort((a,b)=>String(a).localeCompare(String(b)));if(fit.classes.length<2)throw Error('分类训练至少需要2个类别');fit.scale={mean:fit.keys.map(k=>mean(rows.map(r=>Number(r[k])))),std:[]};fit.scale.std=fit.keys.map((k,i)=>Math.sqrt(mean(rows.map(r=>(Number(r[k])-fit.scale.mean[i])**2)))||1);const model=tf.sequential();model.add(tf.layers.dense({inputShape:[fit.keys.length],units:24,activation:'relu'}));model.add(tf.layers.dense({units:12,activation:'relu'}));model.add(tf.layers.dense({units:fit.classes.length,activation:'softmax'}));model.compile({optimizer:tf.train.adam(.003),loss:'categoricalCrossentropy'});fit.network=model;const xs=tf.tensor2d(rows.map(r=>scaled(fit,r))),ys=tf.tensor2d(rows.map(r=>fit.classes.map(c=>c===label(id,r[spec.target])?1:0))),epochs=Math.min(1000,Math.max(1,Math.floor(Number(options.epochs)||30)));try{await model.fit(xs,ys,{epochs,batchSize:Math.min(32,rows.length),shuffle:false,yieldEvery:'never',callbacks:{onEpochEnd:async(e,logs)=>{fit.history.push({epoch:e+1,...logs});progress(e+1,epochs,logs.loss);await new Promise(resolve=>setTimeout(resolve,0));}}});}catch(error){model.dispose();throw error;}finally{xs.dispose();ys.dispose();}}
else for(const [key,rs]of groups(id,rows)){let p=null;if(key&&id==='horner'&&rs.length>=3){const xs=rs.map(r=>Number(r.log_horner)),ys=rs.map(r=>Number(r.pressure)),mx=mean(xs),my=mean(ys),ss=xs.reduce((s,x)=>s+(x-mx)**2,0);if(ss>1e-15){const slope=xs.reduce((s,x,i)=>s+(x-mx)*(ys[i]-my),0)/ss;p={slope,intercept:my-slope*mx};}}if(key&&id==='tracer')p=tracerFit(rs,options);if(p)Object.defineProperty(fit.params,key,{value:p,enumerable:true,writable:true,configurable:true});else fit.warnings.push(`${key||'缺少分组标识'}：样本不足或自变量恒定，未覆盖`);}if(val.length){try{validate(id,val);fit.validation=evaluateMonitoring(fit,await predictMonitoring(fit,val));}catch(error){fit.warnings.push(`验证集未评估：${error.message}`);}}fit.duration=(performance.now()-started)/1000;fit.createdAt=new Date().toISOString();return fit;}
export async function predictMonitoring(fit,rows){if(!Array.isArray(rows)||!rows.length)return [];validate(fit.id,rows,true);const target=specFor(fit.id).target;const withActual=(r,p)=>{const out={...r,...p};if(['event3w','esp'].includes(fit.id)?scalarLabel(r[target]):finite(r[target]))out.actual=['event3w','esp'].includes(fit.id)?label(fit.id,r[target]):Number(r[target]);return out;};if(['event3w','esp'].includes(fit.id)){const tf=globalThis.tf,x=tf.tensor2d(rows.map(r=>scaled(fit,r)));let y;try{y=fit.network.predict(x);const values=await y.array();return rows.map((r,i)=>{const ps=values[i],c=fit.classes[ps.indexOf(Math.max(...ps))];return withActual(r,{prediction:c,predicted_class:c,probabilities:Object.fromEntries(fit.classes.map((c,j)=>[c,ps[j]]))});});}finally{x.dispose();y?.dispose();}}return rows.map(r=>{const key=groupKey(fit.id,r),p=Object.hasOwn(fit.params,key)?fit.params[key]:null;if(!p)return withActual(r,{prediction:null,status:'未覆盖',reason:'该测试或井组没有可用拟合参数'});if(fit.id==='horner')return withActual(r,{prediction:p.intercept+p.slope*Number(r.log_horner),slope:p.slope,intercept:p.intercept,formation_pressure:p.intercept,status:'已拟合'});const concentration=p.A*kernel(Number(r.time_days),Number(r.distance_m),p.v,p.D);return withActual(r,{prediction:concentration,predicted_concentration:concentration,travel_days:Number(r.distance_m)/p.v,v:p.v,D:p.D,A:p.A,status:'已拟合'});});}
export function evaluateMonitoring(fit,results){const target=specFor(fit.id).target;if(!['event3w','esp'].includes(fit.id)){const pairs=results.filter(r=>finite(r.actual??r[target])&&finite(r.prediction));return regressionMetrics(pairs.map(r=>Number(r.actual??r[target])),pairs.map(r=>Number(r.prediction)));}const pairs=results.filter(r=>scalarLabel(r.actual??r[target])).map(r=>[label(fit.id,r.actual??r[target]),r.prediction]);if(!pairs.length)return null;const classes=[...new Set([...fit.classes,...pairs.map(x=>x[0])])];let precision=0,recall=0,f1=0;for(const c of classes){let tp=0,fp=0,fn=0;for(const [a,p]of pairs){if(a===c&&p===c&&fit.classes.includes(c))tp++;else{if(p===c)fp++;if(a===c)fn++;}}const P=tp+fp?tp/(tp+fp):0,R=tp+fn?tp/(tp+fn):0;precision+=P;recall+=R;f1+=P+R?2*P*R/(P+R):0;}return {Accuracy:pairs.filter(([a,p])=>fit.classes.includes(a)&&a===p).length/pairs.length,Precision:precision/classes.length,Recall:recall/classes.length,F1:f1/classes.length,N:pairs.length,UnknownTrueCount:pairs.filter(([a])=>!fit.classes.includes(a)).length};}
